/* Ballot pages. Everything works without JavaScript; this adds:
 * - a live "n of max" counter that disables extra choices,
 * - a receipt code generated in the browser (the server never sees it, only its
 *   SHA-256 commitment), kept in localStorage for this election,
 * - submission with automatic retries using the same one-time key, so a lost
 *   connection can never create a second ballot or a false "accepted" message.
 */
(function () {
  "use strict";
  var ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"; // Crockford base32
  var CODE_LENGTH = 16; // 80 random bits

  function limitChoices() {
    var box = document.querySelector("[data-max-choices]");
    if (!box) { return; }
    var max = parseInt(box.getAttribute("data-max-choices"), 10);
    var counter = document.getElementById("choice-counter");
    function update() {
      var boxes = box.querySelectorAll('input[type="checkbox"]');
      var checked = 0;
      boxes.forEach(function (b) { if (b.checked) { checked += 1; } });
      boxes.forEach(function (b) { b.disabled = !b.checked && checked >= max; });
      if (counter) { counter.textContent = checked + " of " + max + " selected"; }
    }
    box.addEventListener("change", update);
    update();
  }

  function newCode() {
    var bytes = new Uint8Array(CODE_LENGTH);
    window.crypto.getRandomValues(bytes);
    var code = "";
    for (var i = 0; i < bytes.length; i += 1) { code += ALPHABET[bytes[i] & 31]; }
    return code;
  }

  function format(code) { return code.replace(/(.{4})(?=.)/g, "$1-"); }

  function hex(buffer) {
    return Array.prototype.map.call(new Uint8Array(buffer), function (b) {
      return ("0" + b.toString(16)).slice(-2);
    }).join("");
  }

  function store(key, value) {
    try { window.localStorage.setItem(key, value); } catch (e) { /* private mode */ }
  }
  function load(key) {
    try { return window.localStorage.getItem(key); } catch (e) { return null; }
  }

  function setStatus(text) {
    var el = document.getElementById("cast-status");
    if (el) { el.textContent = text; }
  }

  function send(form, attempt) {
    window.fetch(form.action, { method: "POST", body: new FormData(form),
                                credentials: "same-origin" })
      .then(function (response) { return response.text(); })
      .then(function (html) { document.open(); document.write(html); document.close(); })
      .catch(function () {
        if (attempt < 3) {
          setStatus("We could not confirm your ballot yet. Do not close this page. Retrying…");
          window.setTimeout(function () { send(form, attempt + 1); }, 1000 * Math.pow(2, attempt));
        } else {
          setStatus("We still could not confirm your ballot. Do not submit a new one: " +
                    "check its status instead.");
          var check = document.getElementById("check-status");
          if (check) { check.hidden = false; }
        }
      });
  }

  function prepareCast() {
    var form = document.getElementById("cast-form");
    if (!form || !window.crypto || !window.crypto.subtle || !window.fetch ||
        !window.TextEncoder) { return; } // the plain form post still works
    var election = form.getAttribute("data-election");
    var code = null;
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      form.querySelector('button[type="submit"]').disabled = true;
      setStatus("Submitting your ballot…");
      code = code || newCode(); // the same code for every retry from this page
      var data = new TextEncoder().encode("rcpt/v1" + election + code);
      window.crypto.subtle.digest("SHA-256", data).then(function (digest) {
        store("receipt:" + election, code);
        form.querySelector('input[name="receipt_commitment"]').value = hex(digest);
        send(form, 0);
      });
    });
  }

  function fillReceipt() {
    var el = document.getElementById("receipt-code");
    if (!el) { return; }
    var election = el.getAttribute("data-election");
    if (el.getAttribute("data-confirmed") === "1") { store("receipt-ok:" + election, "1"); }
    if (el.textContent.trim()) { return; } // generated by the server (no-JavaScript path)
    var code = load("receipt:" + election);
    el.textContent = code && load("receipt-ok:" + election) ? format(code)
                                                            : "(not saved on this device)";
  }

  limitChoices();
  prepareCast();
  fillReceipt();
}());
